/**
 * `defineTool` — authored at `agent/tools/<name>.ts`.
 *
 * Each file under `agent/tools/` is one tool; the filename becomes the tool
 * name the model sees. Export the definition as the module's default export:
 *
 * ```ts
 * import { defineTool } from "@grok/agent-sdk/tools";
 * import * as z from "zod/v4";
 *
 * // Runs in-process on the agent-serve host (default). Authored MCP
 * // connections are on ctx.host.mcp (also on the Cursor agent via SDK, and
 * // on channel handlers via args.host.mcp).
 * export default defineTool({
 *   description: "Get the current weather for a city.",
 *   inputSchema: z.object({ city: z.string() }),
 *   async execute({ city }, ctx) {
 *     // await ctx.host.mcp.callTool("linear", "list_issues", { ... })
 *     return { city, condition: "Sunny", temperatureF: 72 };
 *   },
 * });
 * ```
 *
 * Park the call for human approval (playground or
 * `POST /v1/session/:id/approvals/:callId`) before `execute` runs:
 *
 * ```ts
 * export default defineTool({
 *   description: "Post a weather alert to ops.",
 *   needsApproval: true,
 *   inputSchema: z.object({ city: z.string(), message: z.string() }),
 *   async execute({ city, message }) {
 *     return { posted: true, city, message };
 *   },
 * });
 * ```
 *
 * Agent-side tools materialize a shell script the Cursor agent invokes
 * (local harness or cloud). JSON args on stdin, result on stdout:
 *
 * ```ts
 * export default defineTool({
 *   description: "Echo a message from the agent workspace.",
 *   execution: "agent",
 *   inputSchema: z.object({ message: z.string() }),
 *   script: `#!/usr/bin/env bash
 * set -euo pipefail
 * message=$(python3 -c 'import json,sys; print(json.load(sys.stdin)["message"])')
 * printf '%s\\n' "$message"
 * `,
 * });
 * ```
 */
import { forwardTimeArgument, missingTimeWindow, schemaTimeWindowKeys } from "./internal/as-of.js";
import { brandDefinition } from "./internal/brand.js";
import { classifyAnnotationsEffect } from "./internal/tool-policy.js";
/**
 * Time-window and effect classifiers the host applies to every tool call.
 * Re-exported for tools that reach other tools themselves (change-monitor
 * `script`): inner calls skip the host gate, so the sandbox applies the same
 * forward-time, omitted-window, and read-only filters.
 */
export { classifyAnnotationsEffect, forwardTimeArgument, missingTimeWindow, schemaTimeWindowKeys };
/**
 * Define a tool. With a zod `inputSchema` (`zod/v3` or `zod/v4`) the input
 * is validated before `execute` runs and typed via inference; with a plain
 * JSON Schema object
 * (or no schema) the input is the raw JSON arguments.
 *
 * Set `execution: "agent"` to materialize a workspace script instead of
 * registering an in-process custom tool.
 *
 * Set `needsApproval: true` (or a predicate) so the host parks the
 * in-flight call until a human approves or denies it.
 */
export function defineTool(config) {
    // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- defineTool's schema generic is erased on ToolDefinition; brandDefinition only adds the kind
    return brandDefinition("tool", config);
}
